#[derive(Clone, Debug, Default, PartialEq)]
pub struct AiRosterSetup {
    pub calls: Vec<AiRosterCall>,
    pub names: Vec<AiRosterSideNames>,
    pub local: Option<StrId>,
    pub humans: Vec<AiRosterHuman>,
    pub unit_scale: f64,
    pub heroes: bool,
    pub demo: bool,
    pub capacity: f64,
    pub prepared: Vec<StrId>,
    pub pads: Vec<F4PadSetup>,
    pub hero_names: Vec<F4HeroSetup>,
}

impl AiRosterSetup {
    pub const WORDS: usize = 18;
    pub const CALLS: usize = 0;
    pub const NAMES: usize = 2;
    pub const LOCAL: usize = 4;
    pub const HUMANS: usize = 6;
    pub const UNIT_SCALE: usize = 8;
    pub const HEROES: usize = 9;
    pub const DEMO: usize = 10;
    pub const CAPACITY: usize = 11;
    pub const PREPARED: usize = 12;
    pub const PADS: usize = 14;
    pub const HERO_NAMES: usize = 16;
    pub fn calls_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[0] as usize; let length = row[1] as usize; heap[start..start + length * 7].chunks_exact(7) }
    pub fn names_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[2] as usize; let length = row[3] as usize; heap[start..start + length * 4].chunks_exact(4) }
    pub fn humans_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[6] as usize; let length = row[7] as usize; heap[start..start + length * 5].chunks_exact(5) }
    pub fn prepared_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[12] as usize; let length = row[13] as usize; heap[start..start + length * 1].chunks_exact(1) }
    pub fn pads_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[14] as usize; let length = row[15] as usize; heap[start..start + length * 29].chunks_exact(29) }
    pub fn hero_names_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[16] as usize; let length = row[17] as usize; heap[start..start + length * 3].chunks_exact(3) }

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 18] = (&mut row[..18]).try_into().unwrap();
        { let at = heap.len(); row[0] = at as f64; row[0 + 1] = self.calls.len() as f64; heap.resize(at + self.calls.len() * 7, 0.0); for (i, e) in self.calls.iter().enumerate() { let mut item = [0.0f64; 7]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 7..at + (i + 1) * 7].copy_from_slice(&item); } }
        { let at = heap.len(); row[2] = at as f64; row[2 + 1] = self.names.len() as f64; heap.resize(at + self.names.len() * 4, 0.0); for (i, e) in self.names.iter().enumerate() { let mut item = [0.0f64; 4]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 4..at + (i + 1) * 4].copy_from_slice(&item); } }
        match &self.local { Some(v) => { row[4] = 0.0; row[4 + 1] = (*v).0 as f64; } None => { row[4] = 1.0; row[4 + 1..4 + 2].fill(0.0); } }
        { let at = heap.len(); row[6] = at as f64; row[6 + 1] = self.humans.len() as f64; heap.resize(at + self.humans.len() * 5, 0.0); for (i, e) in self.humans.iter().enumerate() { let mut item = [0.0f64; 5]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 5..at + (i + 1) * 5].copy_from_slice(&item); } }
        row[8] = self.unit_scale;
        row[9] = if self.heroes { 1.0 } else { 0.0 };
        row[10] = if self.demo { 1.0 } else { 0.0 };
        row[11] = self.capacity;
        { let at = heap.len(); row[12] = at as f64; row[12 + 1] = self.prepared.len() as f64; heap.resize(at + self.prepared.len() * 1, 0.0); for (i, e) in self.prepared.iter().enumerate() { let mut item = [0.0f64; 1]; { let row = &mut item; row[0] = (*e).0 as f64; } heap[at + i * 1..at + (i + 1) * 1].copy_from_slice(&item); } }
        { let at = heap.len(); row[14] = at as f64; row[14 + 1] = self.pads.len() as f64; heap.resize(at + self.pads.len() * 29, 0.0); for (i, e) in self.pads.iter().enumerate() { let mut item = [0.0f64; 29]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 29..at + (i + 1) * 29].copy_from_slice(&item); } }
        { let at = heap.len(); row[16] = at as f64; row[16 + 1] = self.hero_names.len() as f64; heap.resize(at + self.hero_names.len() * 3, 0.0); for (i, e) in self.hero_names.iter().enumerate() { let mut item = [0.0f64; 3]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 3..at + (i + 1) * 3].copy_from_slice(&item); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 18] = (&row[..18]).try_into().unwrap();
        Self {
            calls: { let (at, n) = (word_u32(row[0]) as usize, word_u32(row[0 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 7..at + (i + 1) * 7]; out.push(AiRosterCall::take(&row[0..], heap)); } out },
            names: { let (at, n) = (word_u32(row[2]) as usize, word_u32(row[2 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 4..at + (i + 1) * 4]; out.push(AiRosterSideNames::take(&row[0..], heap)); } out },
            local: if row[4] == 0.0 { Some(StrId(word_u32(row[4 + 1]))) } else { None },
            humans: { let (at, n) = (word_u32(row[6]) as usize, word_u32(row[6 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 5..at + (i + 1) * 5]; out.push(AiRosterHuman::take(&row[0..], heap)); } out },
            unit_scale: row[8],
            heroes: row[9] != 0.0,
            demo: row[10] != 0.0,
            capacity: row[11],
            prepared: { let (at, n) = (word_u32(row[12]) as usize, word_u32(row[12 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 1..at + (i + 1) * 1]; out.push(StrId(word_u32(row[0]))); } out },
            pads: { let (at, n) = (word_u32(row[14]) as usize, word_u32(row[14 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 29..at + (i + 1) * 29]; out.push(F4PadSetup::take(&row[0..], heap)); } out },
            hero_names: { let (at, n) = (word_u32(row[16]) as usize, word_u32(row[16 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 3..at + (i + 1) * 3]; out.push(F4HeroSetup::take(&row[0..], heap)); } out },
        }
    }

}

