        let row: &mut [f64; 17] = (&mut row[..17]).try_into().unwrap();
        row[0] = self.def.0 as f64;
        match &self.base { Some(v) => { row[1] = 0.0; row[1 + 1] = (*v).0 as f64; } None => { row[1] = 2.0; row[1 + 1..1 + 2].fill(0.0); } }
