#[derive(Clone, Debug, Default, PartialEq)]
pub struct AiPostDefinition {
    pub policy: AiPostPolicy,
    pub name: Option<StrId>,
    pub order: Option<f64>,
    pub value_bleed: f64,
    pub spawn_present: Option<bool>,
    pub ally_present: Option<bool>,
    pub ally_count: f64,
    pub capture: Option<AiCapture>,
    pub radius: f64,
    pub yaw: f64,
    pub raw_capture: Option<AiRawCapture>,
    pub spawn_path: bool,
    pub spawn_points: f64,
    pub ally_path: bool,
}

impl AiPostDefinition {
    pub const WORDS: usize = 57;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 57] = (&mut row[..57]).try_into().unwrap();
        self.policy.put(&mut row[0..], heap);
        match &self.name { Some(v) => { row[19] = 0.0; row[19 + 1] = (*v).0 as f64; } None => { row[19] = 2.0; row[19 + 1..19 + 2].fill(0.0); } }
        match &self.order { Some(v) => { row[21] = 0.0; row[21 + 1] = (*v); } None => { row[21] = 1.0; row[21 + 1..21 + 2].fill(0.0); } }
        row[23] = self.value_bleed;
        match &self.spawn_present { Some(v) => { row[24] = 0.0; row[24 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[24] = 1.0; row[24 + 1..24 + 2].fill(0.0); } }
        match &self.ally_present { Some(v) => { row[26] = 0.0; row[26 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[26] = 1.0; row[26 + 1..26 + 2].fill(0.0); } }
        row[28] = self.ally_count;
        match &self.capture { Some(v) => { row[29] = 0.0; v.put(&mut row[29 + 1..], heap); } None => { row[29] = 1.0; row[29 + 1..29 + 7].fill(0.0); } }
        row[36] = self.radius;
        row[37] = self.yaw;
        match &self.raw_capture { Some(v) => { row[38] = 0.0; v.put(&mut row[38 + 1..], heap); } None => { row[38] = 1.0; row[38 + 1..38 + 16].fill(0.0); } }
        row[54] = if self.spawn_path { 1.0 } else { 0.0 };
        row[55] = self.spawn_points;
        row[56] = if self.ally_path { 1.0 } else { 0.0 };
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 57] = (&row[..57]).try_into().unwrap();
        Self {
            policy: AiPostPolicy::take(&row[0..], heap),
            name: if row[19] == 0.0 { Some(StrId(word_u32(row[19 + 1]))) } else { None },
            order: if row[21] == 0.0 { Some(row[21 + 1]) } else { None },
            value_bleed: row[23],
            spawn_present: if row[24] == 0.0 { Some(row[24 + 1] != 0.0) } else { None },
            ally_present: if row[26] == 0.0 { Some(row[26 + 1] != 0.0) } else { None },
            ally_count: row[28],
            capture: if row[29] == 0.0 { Some(AiCapture::take(&row[29 + 1..], heap)) } else { None },
            radius: row[36],
            yaw: row[37],
            raw_capture: if row[38] == 0.0 { Some(AiRawCapture::take(&row[38 + 1..], heap)) } else { None },
            spawn_path: row[54] != 0.0,
            spawn_points: row[55],
            ally_path: row[56] != 0.0,
        }
    }

}

