#[derive(Clone, Debug, Default, PartialEq)]
pub struct AiWorldContent {
    pub classes: Vec<AiUnitClass>,
    pub weapons: Vec<DefId>,
    pub weapon_data: Vec<AiWeaponData>,
    pub items: Vec<AiItemDefinition>,
    pub posts: Vec<AiPostDefinition>,
    pub hulls: Vec<AiHullDefinition>,
    pub props: Vec<AiPropDefinition>,
}

impl AiWorldContent {
    pub const WORDS: usize = 14;
    pub const CLASSES: usize = 0;
    pub const WEAPONS: usize = 2;
    pub const WEAPON_DATA: usize = 4;
    pub const ITEMS: usize = 6;
    pub const POSTS: usize = 8;
    pub const HULLS: usize = 10;
    pub const PROPS: usize = 12;
    pub fn classes_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[0] as usize; let length = row[1] as usize; heap[start..start + length * 63].chunks_exact(63) }
    pub fn weapons_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[2] as usize; let length = row[3] as usize; heap[start..start + length * 1].chunks_exact(1) }
    pub fn weapon_data_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[4] as usize; let length = row[5] as usize; heap[start..start + length * 2].chunks_exact(2) }
    pub fn items_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[6] as usize; let length = row[7] as usize; heap[start..start + length * 17].chunks_exact(17) }
    pub fn posts_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[8] as usize; let length = row[9] as usize; heap[start..start + length * 57].chunks_exact(57) }
    pub fn hulls_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[10] as usize; let length = row[11] as usize; heap[start..start + length * 80].chunks_exact(80) }
    pub fn props_rows<'a>(row: &[f64], heap: &'a [f64]) -> std::slice::ChunksExact<'a, f64> { let start = row[12] as usize; let length = row[13] as usize; heap[start..start + length * 149].chunks_exact(149) }

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 14] = (&mut row[..14]).try_into().unwrap();
        { let at = heap.len(); row[0] = at as f64; row[0 + 1] = self.classes.len() as f64; heap.resize(at + self.classes.len() * 63, 0.0); for (i, e) in self.classes.iter().enumerate() { let mut item = [0.0f64; 63]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 63..at + (i + 1) * 63].copy_from_slice(&item); } }
        { let at = heap.len(); row[2] = at as f64; row[2 + 1] = self.weapons.len() as f64; heap.resize(at + self.weapons.len() * 1, 0.0); for (i, e) in self.weapons.iter().enumerate() { let mut item = [0.0f64; 1]; { let row = &mut item; row[0] = (*e).0 as f64; } heap[at + i * 1..at + (i + 1) * 1].copy_from_slice(&item); } }
        { let at = heap.len(); row[4] = at as f64; row[4 + 1] = self.weapon_data.len() as f64; heap.resize(at + self.weapon_data.len() * 2, 0.0); for (i, e) in self.weapon_data.iter().enumerate() { let mut item = [0.0f64; 2]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 2..at + (i + 1) * 2].copy_from_slice(&item); } }
        { let at = heap.len(); row[6] = at as f64; row[6 + 1] = self.items.len() as f64; heap.resize(at + self.items.len() * 17, 0.0); for (i, e) in self.items.iter().enumerate() { let mut item = [0.0f64; 17]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 17..at + (i + 1) * 17].copy_from_slice(&item); } }
        { let at = heap.len(); row[8] = at as f64; row[8 + 1] = self.posts.len() as f64; heap.resize(at + self.posts.len() * 57, 0.0); for (i, e) in self.posts.iter().enumerate() { let mut item = [0.0f64; 57]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 57..at + (i + 1) * 57].copy_from_slice(&item); } }
        { let at = heap.len(); row[10] = at as f64; row[10 + 1] = self.hulls.len() as f64; heap.resize(at + self.hulls.len() * 80, 0.0); for (i, e) in self.hulls.iter().enumerate() { let mut item = [0.0f64; 80]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 80..at + (i + 1) * 80].copy_from_slice(&item); } }
        { let at = heap.len(); row[12] = at as f64; row[12 + 1] = self.props.len() as f64; heap.resize(at + self.props.len() * 149, 0.0); for (i, e) in self.props.iter().enumerate() { let mut item = [0.0f64; 149]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 149..at + (i + 1) * 149].copy_from_slice(&item); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 14] = (&row[..14]).try_into().unwrap();
        Self {
            classes: { let (at, n) = (word_u32(row[0]) as usize, word_u32(row[0 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 63..at + (i + 1) * 63]; out.push(AiUnitClass::take(&row[0..], heap)); } out },
            weapons: { let (at, n) = (word_u32(row[2]) as usize, word_u32(row[2 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 1..at + (i + 1) * 1]; out.push(DefId(word_u32(row[0]))); } out },
            weapon_data: { let (at, n) = (word_u32(row[4]) as usize, word_u32(row[4 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 2..at + (i + 1) * 2]; out.push(AiWeaponData::take(&row[0..], heap)); } out },
            items: { let (at, n) = (word_u32(row[6]) as usize, word_u32(row[6 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 17..at + (i + 1) * 17]; out.push(AiItemDefinition::take(&row[0..], heap)); } out },
            posts: { let (at, n) = (word_u32(row[8]) as usize, word_u32(row[8 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 57..at + (i + 1) * 57]; out.push(AiPostDefinition::take(&row[0..], heap)); } out },
            hulls: { let (at, n) = (word_u32(row[10]) as usize, word_u32(row[10 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 80..at + (i + 1) * 80]; out.push(AiHullDefinition::take(&row[0..], heap)); } out },
            props: { let (at, n) = (word_u32(row[12]) as usize, word_u32(row[12 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 149..at + (i + 1) * 149]; out.push(AiPropDefinition::take(&row[0..], heap)); } out },
        }
    }

}

